"use strict";
import { Link } from "react-router-dom";
import { ExternalLink } from "theme/components/Links";
import { Text } from "ui/src";
const LinkStyle = {
  textDecoration: "none",
  height: "unset",
  padding: 0
};
const LinkTextStyle = {
  color: "$neutral2",
  hoverStyle: {
    opacity: 0.6
  }
};
export function MenuLink({
  label,
  href,
  internal,
  closeMenu,
  textVariant = "subheading1"
}) {
  return internal ? <Link to={href} onClick={closeMenu} style={LinkStyle}>
      <Text variant={textVariant} {...LinkTextStyle}>
        {label}
      </Text>
    </Link> : <ExternalLink href={href} onClick={closeMenu} style={LinkStyle}>
      <Text variant={textVariant} {...LinkTextStyle}>
        {label}
      </Text>
    </ExternalLink>;
}
