"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import { useCurrency } from "hooks/Tokens";
import { useScroll } from "hooks/useScroll";
import { TokenCloud } from "pages/Landing/components/TokenCloud";
import { RiseIn } from "pages/Landing/components/animations";
import { Swap } from "pages/Swap";
import { useCallback, useMemo } from "react";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import { serializeSwapStateToURLParameters } from "state/swap/hooks";
import { Flex, Text, useMedia } from "ui/src";
import { INTERFACE_NAV_HEIGHT } from "ui/src/theme";
import { useEnabledChains } from "uniswap/src/features/chains/hooks/useEnabledChains";
export function Hero({ scrollToRef, transition }) {
  const media = useMedia();
  const { height: scrollPosition } = useScroll({ enabled: !media.sm });
  const { defaultChainId } = useEnabledChains();
  const initialInputCurrency = useCurrency("ETH", defaultChainId);
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { translateY, opacityY } = useMemo(
    () => ({
      translateY: !media.sm ? -scrollPosition / 7 : 0,
      opacityY: !media.sm ? 1 - scrollPosition / 1e3 : 1
    }),
    [media.sm, scrollPosition]
  );
  const swapRedirectCallback = useCallback(
    ({ inputCurrency, outputCurrency, typedValue, independentField, chainId }) => {
      navigate(
        `/swap${serializeSwapStateToURLParameters({
          inputCurrency,
          outputCurrency,
          typedValue,
          independentField,
          chainId
        })}`
      );
    },
    [navigate]
  );
  return <Flex
    position="relative"
    justifyContent="center"
    y={translateY}
    opacity={opacityY}
    minWidth="100%"
    minHeight="100vh"
    height="min-content"
    pt={INTERFACE_NAV_HEIGHT}
    pointerEvents="none"
  >
      {!media.sm && <TokenCloud />}

      <Flex
    alignSelf="center"
    maxWidth="85vw"
    pointerEvents="none"
    pt={48}
    gap="$gap20"
    transform={`translate(0px, ${translateY}px)`}
    opacity={opacityY}
    $lg={{ pt: 24 }}
    $sm={{ pt: 8 }}
    $platform-web={{
      transition: transition ? "shrinkAndFade 1s ease-in-out forwards" : void 0
    }}
  >
        <Flex row maxWidth={920} gap={"$gap12"} justifyContent="center" alignItems="center" pointerEvents="none">
          <LogoProvider size={media.sm ? 36 : 48} />
          <Text
    variant="heading1"
    fontSize={36}
    textAlign="center"
    fontWeight="$book"
    fontFamily={"Inter"}
    $md={{ variant: "heading2", fontSize: 28 }}
    $sm={{ variant: "heading2", fontSize: 24 }}
  >
            Aborean Finance
          </Text>
        </Flex>

        <RiseIn delay={0.4}>
          <Flex
    pointerEvents="auto"
    width={480}
    p="$padding8"
    borderRadius="$rounded24"
    backgroundColor="$surface1"
    maxWidth="100%"
    enterStyle={{ opacity: 0 }}
  >
            <Swap
    hideHeader
    hideFooter
    syncTabToUrl={false}
    chainId={defaultChainId}
    initialInputCurrency={initialInputCurrency}
    swapRedirectCallback={swapRedirectCallback}
    usePersistedFilteredChainIds
  />
          </Flex>
        </RiseIn>

        <RiseIn delay={0.3}>
          <Text
    variant="body1"
    textAlign="center"
    maxWidth={430}
    color="$neutral2"
    $short={{ variant: "body2" }}
  />
        </RiseIn>
      </Flex>

      <Flex flex={1} />
    </Flex>;
}
