"use strict";
import { PreferencesHeader } from "components/NavBar/PreferencesMenu/Header";
import { PreferencesView } from "components/NavBar/PreferencesMenu/shared";
import styled, { useTheme } from "lib/styled-components";
import { ChevronRight } from "react-feather";
import { Trans, useTranslation } from "react-i18next";
import { ThemeSelector } from "theme/components/ThemeToggle";
import { Flex, Text } from "ui/src";
import { useAppFiatCurrency } from "uniswap/src/features/fiatCurrency/hooks";
import { useCurrentLanguage, useLanguageInfo } from "uniswap/src/features/language/hooks";
const Pref = styled.div`
  display: flex;
  flex-direction: row;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
`;
const StyledChevron = styled(ChevronRight)`
  opacity: 0.8;
`;
const SelectButtonContainer = styled.div`
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  width: 100%;
  justify-content: end;
  transition: opacity 0.2s;
  &:hover {
    opacity: 0.6;
  }
`;
function SelectButton({ label, onClick }) {
  const theme = useTheme();
  return <SelectButtonContainer onClick={onClick}>
      <Text variant="buttonLabel2" color="$neutral1">
        {label}
      </Text>
      <StyledChevron size={24} color={theme.neutral1} />
    </SelectButtonContainer>;
}
export function PreferenceSettings({
  setSettingsView,
  showHeader = true,
  showThemeLabel = true
}) {
  const { t } = useTranslation();
  const activeLocalCurrency = useAppFiatCurrency();
  const activeLanguage = useCurrentLanguage();
  const languageInfo = useLanguageInfo(activeLanguage);
  const items = [
    {
      label: showThemeLabel ? t("themeToggle.theme") : void 0,
      component: <ThemeSelector compact fullWidth={!showThemeLabel} />
    },
    {
      label: t("common.language"),
      component: <SelectButton label={languageInfo.displayName} onClick={() => setSettingsView(PreferencesView.LANGUAGE)} />
    },
    {
      label: t("common.currency"),
      component: <SelectButton label={activeLocalCurrency} onClick={() => setSettingsView(PreferencesView.CURRENCY)} />
    }
  ];
  return <>
      {showHeader && <PreferencesHeader>
          <Trans i18nKey="globalPreferences.title" />
        </PreferencesHeader>}

      <Flex gap="$gap12">
        {items.map(({ label, component }, index) => <Pref key={`${label}_${index}`}>
            {label && <Text variant="body2" color="$neutral2" textAlign="left">
                {label}
              </Text>}
            {component}
          </Pref>)}
      </Flex>
    </>;
}
